// Note: Since category needs id from product detail, it can't be server side rendered atm
// until we can do dependent query on server
const {
  data: category,
  isError: isCategoryError,
  error: categoryError,
} = useCategory({
  parameters: {
    // SDK param widening — `useCategory` is a no-op until the product resolves, exactly as
    // in the base file.
    id: productResponse?.primaryCategoryId as string,
    levels: 1,
  },
});

/****************************** Colour Swatches (SFCC-91) ***********************/
// urlColour is the query-string colour param, read on every render so it is always current.
// ZimmColourSwatchGroup falls back to the first offered colour for *display* when this is
// absent (a bare /product/<id> load with no explicit selection yet), but that fallback is
// local/cosmetic only — it never reaches useDerivedProduct inside ProductView, so the actual
// resolved variant (and anything keyed off it: wishlist, Add to Bag) stays colourless until
// the shopper clicks a swatch. The effect below closes that gap by writing a real default into
// the URL, the one channel useDerivedProduct actually reads.
const urlColour = new URLSearchParams(location.search).get(SFCC_COLOUR_ATTRIBUTE_ID) ?? undefined;

/****************************** Sets and Bundles *********************************/
const [childProductSelection, setChildProductSelection] = useState<Record<string, ChildProductSelection>>({});
const [childProductOrderability, setChildProductOrderability] = useState<Record<string, ChildProductOrderability>>(
  {},
);
const [selectedBundleQuantity, setSelectedBundleQuantity] = useState(1);
const childProductRefs = React.useRef<Record<string, ChildProductRef>>({});
// Deviation from the base file: `?.` on `type`. The base reads `productResponse?.type.set`,
// which throws if the API ever returns a product without `type` (the SDK types it optional).
// The two only differ in that already-broken case.
const isProductASet = productResponse?.type?.set;
const isProductABundle = productResponse?.type?.bundle;

const childVariantIds =
  isProductABundle || isProductASet
    ? Object.keys(childProductSelection)?.map(
        (key) => childProductSelection[key].variant?.productId || childProductSelection[key].product?.id,
      )
    : [];

const { data: variantProductData } = useProducts(
  {
    parameters: {
      // SDK param widening — the base file joins the ids itself and the SDK forwards the
      // value verbatim into the query string.
      ids: childVariantIds.join(',') as unknown as string[],
      allImages: false,
      ...(selectedInventoryId ? { inventoryIds: selectedInventoryId } : {}),
      expand: ['availability', 'variations'],
      select: '(data.(id,inventory,inventories,master))',
    },
  },
  {
    enabled: childVariantIds.length > 0,
    keepPreviousData: true,
  },
);

const product: SfccProduct = useProductInventory(
  productResponse,
  variantProductData,
  selectedInventoryId,
  isProductASet,
  isProductABundle,
);

/**************** Error Handling ****************/

if (isProductError) {
  const errorStatus = (productError as CommerceApiError | null)?.response?.status;
  switch (errorStatus) {
    case 404:
      throw new HTTPNotFound('Product Not Found.');
    default:
      throw new HTTPError(errorStatus, `HTTP Error ${errorStatus} occurred.`);
  }
}
if (isCategoryError) {
  const errorStatus = (categoryError as CommerceApiError | null)?.response?.status;
  switch (errorStatus) {
    case 404:
      throw new HTTPNotFound('Category Not Found.');
    default:
      throw new HTTPError(errorStatus, `HTTP Error ${errorStatus} occurred.`);
  }
}

const [primaryCategory, setPrimaryCategory] = useState<SfccCategory>(category);
const variant = useVariant(product);

// SFCC-434 fix — ZimmColourSwatchGroup falls back to the first offered colour for *display*
// when urlColour is absent (a bare /product/<id> load with no explicit selection yet), but
// that fallback is local/cosmetic only — it never reaches useDerivedProduct inside ProductView,
// so the actual resolved variant (and anything keyed off it: wishlist, Add to Bag) stays
// colourless until the shopper clicks a swatch. This effect closes that gap by writing a real
// default into the URL, the one channel useDerivedProduct actually reads — mirrors the existing
// pid-sync effect below (`history.replace` on `variant` change), just firing earlier, before a
// full variant can resolve at all, since useDerivedProduct needs a colour in the URL first.
//
// Sourced from variationAttributes[].values[] (the colour attribute's own value list), NOT
// variants[] (the master's raw SKU-combination list) — confirmed via live product data
// (SFCC-434 investigation) that these two have genuinely different orders: variationAttributes'
// values come back in a deliberate, merchandiser-curated sequence (e.g. Black, Butter, Icy
// Mint, Grey Heather, White), while variants[] is ordered by SKU combination with no such
// curation — reading variants[] first-orderable picked "White" purely because of where that
// SKU happened to fall in the combination list, not because it was first/default in any
// meaningful sense.
useEffect(() => {
  if (urlColour) return;
  // Guard against stale product data from a previous PDP navigation — only read
  // variationAttributes and modify the URL once the SDK has returned data for the
  // product actually being requested.
  if (product?.id !== requestedProductId) return;
  const colourAttr = product?.variationAttributes?.find((a: { id: string }) => a.id === SFCC_COLOUR_ATTRIBUTE_ID);
  // Intentionally no image guard here — some products return orderable colours without image
  // data in the variation attributes response, which would cause defaultColourValue to be
  // undefined and break initial colour selection entirely. ZimmColourSwatchGroup handles
  // imageless values separately on its own render cycle.
  const defaultColourValue = (colourAttr?.values as SfccSwatchAttrValue[] | undefined)?.find(
    (v) => v.orderable !== false,
  )?.value;
  if (!defaultColourValue) return;
  const params = new URLSearchParams(location.search);
  params.set(SFCC_COLOUR_ATTRIBUTE_ID, defaultColourValue);
  history.replace(`${location.pathname}?${params.toString()}`);
}, [urlColour, product, requestedProductId]);

// SFCC-194 — Was/Now sale price.
//
// Two URL states need correct priceData (mirrors feature/SFCC-194_pdp-was-now-sale-price):
//
//   Colour-only  → ?color=JJ8UTXX           (no pid; product is still the master)
//   Colour+size  → ?color=JJ8UTXX&pid=…M    (pid present; product switches to standalone
//                                              variant which lacks tieredPrices reliably)
//
// Strategy: keep the master product's variants[] as the authoritative tieredPrices source.
// Filter them by pid (exact) or colour (set) from the URL, then call getPriceData on the
// scoped result. This is overridden into renderHeader so the base ProductView's own
// getPriceData call (which reads the standalone variant and loses tieredPrices) is bypassed.
const masterProductRef = useRef<SfccProduct | null>(null);
useEffect(() => {
  // Guard matches exactly what the memo reads from the cache: id (for the
  // cachedMasterMatchesCurrent check) and variants[] (for the filter). A partial SFCC
  // response that satisfies type.master but lacks either field is not useful — skip it
  // rather than writing a cache entry that would fall through to the deep-link fallback
  // one guard too late.
  if (productResponse?.type?.master && productResponse.id && productResponse.variants?.length) {
    masterProductRef.current = productResponse;
  }
}, [productResponse]);

const urlPid = urlParams.get('pid') ?? undefined;
const variantScopedPriceData = useMemo(
  () => selectVariantScopedPriceData(product, masterProductRef.current, urlPid, urlColour),
  // Re-runs when the fetched product changes (standalone variant arrives) or the URL
  // selection changes — both are signals the displayed price must update.
  // masterProductRef is a ref so it is intentionally absent from deps.

  [urlPid, urlColour, product],
);

// True while keepPreviousData holds stale product data during a variant re-fetch (size
// selection). The fetched product id hasn't caught up with the URL yet, so any price
// derived from the old product is unreliable — suppress it entirely until the fetch
// settles rather than showing a briefly-incorrect Was/Now figure.

import React, { useEffect, useRef, useState } from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { useHistory } from 'react-router-dom';
import { defineMessages, useIntl } from 'react-intl';
import { ZimmColourSwatch } from '../../atoms/zimmColourSwatch';
import { ChevronLeftIcon, ChevronRightIcon } from '../../../icons';
import { SWATCHES_PER_PAGE } from './zimmColourSwatchGroupShared';

const messages = defineMessages({
  groupLabel: { id: 'colour_swatches.group.label', defaultMessage: 'Colour' },
  label: { id: 'colour_swatches.label', defaultMessage: 'Colour:' },
  paginationGroupLabel: { id: 'colour_swatches.pagination.group_label', defaultMessage: 'Colour swatch pages' },
  next: { id: 'colour_swatches.pagination.next', defaultMessage: 'Next colours' },
  previous: { id: 'colour_swatches.pagination.previous', defaultMessage: 'Previous colours' },
});

const ZIMM_COLOUR_SWATCH_GROUP_RECIPE = 'ZimmColourSwatchGroup';

/** One selectable colour variation as the molecule expects it — pre-mapped from the raw SFCC shape. */
export type ZimmColourSwatchValue = {
  value: string;
  name: string;
  /** Resolved swatch fill image URL. Absence means the colour has no swatch image and is withheld. */
  imageUrl?: string;
  /** Router destination URL for this colour. Absent on the quick-view modal path. */
  href?: string;
  /** Mirrors SFCC's `orderable` flag. Unavailable colours are withheld (not shown as disabled). */
  orderable?: boolean;
  /**
   * When true, clicking navigates via a native anchor (full page reload) rather than a router
   * Link. Set for related-colour swatches (SFCC-708) that link to a different master product.
   */
  forceReload?: boolean;
};

type ZimmColourSwatchGroupProps = {
  values: ZimmColourSwatchValue[];
  /** Currently selected colour value (from URL / variation params). */
  selectedValue?: string;
  /**
   * Display label for the colour group. Defaults to the i18n "Colour" value.
   * Pass an explicit value when the SFCC attribute display name differs from the default.
   */
  label?: string;
  /**
   * When `label` is a field name (e.g. "Colour"), the group appends ":" itself — the default.
   * Set false for a lead-in phrase that already reads correctly on its own (e.g. "Also
   * available in"), where an appended colon would be wrong.
   */
  appendColon?: boolean;
  /**
   * Selection callback for the linkless path (no `href` on values). Called on click and
   * arrow-key navigation. Not needed on the PDP, where each value carries an `href` and
   * selection is handled by router navigation.
   */
  onSelect?: (value: string) => void;
  /**
   * Tile shape for every swatch in the group. Defaults to `'square'` (main PDP) — zero
   * behaviour change for every existing caller. `'circle'` is the SFCC-731 gallery overlay's
   * 20px, underline-selected tile.
   */
  variant?: 'square' | 'circle';
};

/**
 * Molecule — the full colour-swatch group: label row (name + pagination arrows), and a
 * `[role=radiogroup]` swatch strip of `ZimmColourSwatch` atoms with roving tabindex and
 * keyboard navigation.
 *
 * When only one offered colour exists, the label and name render but the swatch row is
 * suppressed (nothing to choose between). Colours without a swatch image or marked
 * non-orderable are withheld entirely.
 */
export const ZimmColourSwatchGroup = ({
  values,
  selectedValue,
  label,
  appendColon = true,
  onSelect,
  variant = 'square',
}: ZimmColourSwatchGroupProps) => {
  const intl = useIntl();
  const groupLabel = label ?? intl.formatMessage(messages.groupLabel);
  const labelText = label != null ? (appendColon ? `${label}:` : label) : intl.formatMessage(messages.label);

  // Filter to only offered (orderable + swatch image populated) colours.
  const offered = values.filter((v) => Boolean(v.imageUrl) && v.orderable !== false);

  // Falls back to the first offered colour when selectedValue doesn't match anything (e.g. the
  // caller couldn't resolve a default yet) — single source of truth so the label, the swatch
  // tiles, and the pagination/tabindex logic below never disagree about which one is "selected".
  // Declared here (not further down, closer to where selectedName/isSelected consume it) so the
  // auto-advance effect and roving-tabindex calc below can use it too — previously only the
  // label had an equivalent fallback (via its own `?? offered[0]?.name`), and separately the
  // pagination effect below read the raw selectedValue directly, so a fallback-selected colour
  // could resolve to a swatch that was on a completely different (non-visible) page than the one
  // the label showed the name for.
  const effectiveSelectedValue = offered.some((v) => v.value === selectedValue) ? selectedValue : offered[0]?.value;

  const isPaginated = offered.length > SWATCHES_PER_PAGE;
  const pageCount = Math.ceil(offered.length / SWATCHES_PER_PAGE);

  const [page, setPage] = useState(0);

  // Auto-advance to the page containing the effectively-selected value on mount or when it
  // changes (e.g. browser back/forward lands on a colour that is off page 0, or the fallback
  // above resolves to offered[0] on page 0 while the shopper was previously viewing a later
  // page). Keyed off effectiveSelectedValue, not the raw selectedValue prop — matching every
  // other selection-driven calculation in this component — so the page displayed always agrees
  // with the swatch that's actually being rendered as selected.
  // Derived before the effect so it can be included in the dependency list — an equal-length
