// --- Normal (published) home ---

const HomeNormal = () => {
  const einstein = useEinstein();
  const { pathname } = useLocation();

  const { res } = useServerContext();
  if (res) {
    res.set(
      'Cache-Control',
      `s-maxage=${MAX_CACHE_AGE as number}, stale-while-revalidate=${STALE_WHILE_REVALIDATE as number}`,
    );
  }

  // useMultiSite ships untyped from the base SFCC package — same cast footer/index.tsx,
  // useHeaderNav.ts, and uiCopyProvider/index.tsx already use for this exact lookup.
  const { locale: siteLocale } = useMultiSite() as { locale?: { id: string } };
  const locale = siteLocale?.id ?? CONTENTFUL_FALLBACK_LOCALE;

  const { data: contentfulData, isLoading: contentfulLoading } = useContentfulEntries<HomepageEntry>(
    'homepage',
    false,
    locale,
  );
  const homepageContent = useContentfulLiveUpdates(contentfulData?.[0] ?? null);

  useEffect(() => {
    einstein.sendViewPage(pathname);
  }, []);

  if (contentfulLoading) {
    return (
      <Box display="flex" justifyContent="center" py={16}>
        <Spinner size="xl" />
      </Box>
    );
  }

  if (!homepageContent) return null;

  return <HomepageContent />;
};

